  const expense=(await pool.query(`SELECT e.source,e.external_id::text id,e.month::int AS expense_month,sum(e.net_cents-e.refund_cents)::bigint value FROM civica.expenses e JOIN civica.active_expense_publications a ON a.source=e.source AND a.year=e.year AND a.batch_id=e.batch_id WHERE e.source IN (${marks}) AND e.year=$${sources.length+1} GROUP BY e.source,e.external_id,e.month`,[...sources,year])).rows;
  const expBy=new Map<string,number[]>();for(const e of expense){const p=profiles.get(`${e.source}:${e.id}`);const k=partyAtDate(p,`${year}-${String(e.expense_month).padStart(2,'0')}-15`),v=expBy.get(`${k}:${e.source}:${e.id}`)??[];v.push(Number(e.value));expBy.set(`${k}:${e.source}:${e.id}`,v)}
  const partyExpenses=new Map<string,number[]>();for(const [k,v] of expBy){const party=k.split(':')[0]!,xs=partyExpenses.get(party)??[];xs.push(v.reduce((a,b)=>a+b,0));partyExpenses.set(party,xs)}for(const [party,v] of partyExpenses){const row=get(party);row.expenseMedianCents=median(v);row.expenseSample=v.length;}
  const presence=(await Promise.all(sources.map(async s=>(await pool.query(`SELECT $1::text source,p.external_id::text id,op.days_present::double precision numerator,op.days_total::double precision denominator FROM civica_votes_presence_poc.official_presence op JOIN civica_people_poc.profiles p ON p.source=$1 AND p.external_id=op.external_id WHERE op.year=$2`,[s,year])).rows))).flat();
  const presenceBy=new Map<string,number[]>();for(const x of presence){const p=profiles.get(`${x.source}:${x.id}`);if(!p||!Number(x.denominator))continue;const party=partyAtDate(p,`${year}-10-01`);const v=presenceBy.get(party)??[];v.push(Number(x.numerator)/Number(x.denominator));presenceBy.set(party,v)}for(const [party,v] of presenceBy){const row=get(party);row.presenceMedian=median(v);row.presenceSample=v.length;}
