  const rapporteurs=(await pool.query(`SELECT source,payload FROM civica.legislative_appointments WHERE source IN (${marks}) AND kind='rapporteurship'`,sources)).rows;for(const a of rapporteurs){const profile=profiles.get(`${a.source}:${a.payload?.personExternalId}`);const party=partyAtDate(profile,a.payload?.start??`${year}-12-31`);if(party&&String(a.payload?.start??'').startsWith(String(year)))get(party).rapporteurships++;}
  for(const r of rows.values())delete r.participationValues;
  const filtered=[...rows.values()].filter(r=>!search||searchText(r.party).includes(searchText(search))).sort((a,b)=>b.senators+b.deputies-a.senators-a.deputies||a.party.localeCompare(b.party));
  const availableYears=(await pool.query(`SELECT DISTINCT year::int AS yr FROM civica.active_expense_publications WHERE source IN (${marks}) ORDER BY yr DESC`,sources)).rows.map(r=>Number(r.yr));
  const to=new Date().toISOString().slice(0,10), panorama={year,house,rows:filtered,coverage:{availability:filtered.length?'available':'unavailable',source:source??'multiple',period:{from:`${year}-01-01`,to,grain:'year'},batchId:null,note:'Representação usa o cadastro ativo; despesas e participação usam filiação válida no período.',sampleSize:filtered.length}};
  // The public party contract must select the first *usable* option.  The
  // newest deliberation is not necessarily a nominal vote (and therefore
