  const expenses=expenseRows.map(r=>({source:String(r.source),externalId:String(r.external_id),batchId:String(r.batch_id),year:Number(r.year),month:Number(r.month),recordKey:String(r.record_key),categoryCode:String(r.category_code??''),category:String(r.category??''),supplier:r.supplier==null?null:String(r.supplier),supplierDocument:r.supplier_document==null?null:String(r.supplier_document),documentNumber:r.document_number==null?null:String(r.document_number),documentId:r.document_id==null?null:String(r.document_id),documentUrl:r.document_url==null?null:String(r.document_url),issuedAt:r.issued_at==null?null:String(r.issued_at),grossCents:r.gross_cents==null?null:Number(r.gross_cents),deductionCents:Number(r.deduction_cents??0),netCents:Number(r.net_cents??0),refundCents:Number(r.refund_cents??0),installment:r.installment==null?null:Number(r.installment),detail:r.detail==null?null:String(r.detail),rawId:String(r.raw_id??'')}));
  const expenseYears=[...new Set(expenses.map(x=>x.year))].sort((a,b)=>b-a); const expenseCoverage=expenseYears.map(year=>{const rows=expenses.filter(x=>x.year===year),months=[...new Set(rows.map(x=>x.month))].sort((a,b)=>a-b);return {year,months:months.length,recordCount:rows.length,complete:months.length===12,availability:rows.length?'available':'unavailable',source,period:{from:`${year}-01-01`,to:`${year}-12-31`,grain:'year'},batchId:rows[0]?.batchId??null,publishedAt:null,note:rows.length?'Despesas publicadas no PostgreSQL.':'Nenhuma despesa publicada neste ano.',sampleSize:rows.length};});
  const activityRows=needsActivity?(await pool.query(`SELECT a.proposal_id,a.person_external_id,p.type,p.number,p.year,p.label,p.summary,p.status,p.functional_group,p.presented_at,p.raw_id FROM civica_poc.proposal_authors a JOIN civica_poc.active_publications ap ON ap.source=a.source AND ap.batch_id=a.batch_id LEFT JOIN civica_poc.proposals p ON p.source=a.source AND p.external_id=a.proposal_id JOIN civica_poc.active_publications pp ON pp.source=p.source AND pp.batch_id=p.batch_id WHERE a.source=$1 AND a.person_external_id=$2 ORDER BY p.presented_at DESC NULLS LAST LIMIT 100`,[source,id])).rows:[];
