  const legacyInstant=(value:any)=>{if(value==null)return null;const raw=String(value);if(source==='senado'){if(value instanceof Date)return value.toISOString().slice(0,10);if(/^\d{4}-\d{2}-\d{2}(?:T00:00:00(?:\.000)?(?:Z)?|$)/.test(raw))return raw.slice(0,10);}if(value instanceof Date){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(value).replace(' ','T');}const d=new Date(raw);if(!Number.isFinite(d.getTime()))return raw;return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(d).replace(' ','T');};
  const proposals=activityRows.map(r=>({source,externalId:String(r.proposal_id),type:r.type?String(r.type):null,number:r.number==null?null:String(r.number),year:r.year==null?null:Number(r.year),label:r.label?String(r.label):null,summary:r.summary?String(r.summary):null,status:r.status?String(r.status):null,functionalGroup:r.functional_group?String(r.functional_group):null,presentedAt:legacyInstant(r.presented_at),officialUrl:source==='camara'?`https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=${r.proposal_id}`:`https://www25.senado.leg.br/web/atividade/materias/-/materia/${r.proposal_id}`,rawId:r.raw_id==null?null:String(r.raw_id),...(source==='camara'?{catalogRole:'catalog',discoveredByProposalId:null,nextProposalId:null,previousProposalId:null,principalProposalId:null,relationshipEvidence:null}:{})}));
