function propositionFilter(query:any, values:any[], includeGroup=true){
  const where=['TRUE','ap.source=p.source','ap.batch_id=p.batch_id'];
  const add=(sql:string,value:any)=>{values.push(value);where.push(sql.replace('$N',`$${values.length}`));};
  if(query?.source)add('p.source=$N',query.source);
  if(query?.type)add('p.type=$N',query.type);
  if(query?.identifierYear??query?.year)add('p.year=$N',query.identifierYear??query?.year);if(query?.presentedYear)add('p.presented_year=$N',query.presentedYear);
  if(includeGroup&&query?.group)add('p.functional_group=$N',query.group);
  if(query?.author)add('EXISTS (SELECT 1 FROM civica_poc.proposal_authors a WHERE a.source=p.source AND a.proposal_id=p.external_id AND a.search_name LIKE $N)',`%${searchText(query.author)}%`);
  if(query?.theme)add('EXISTS (SELECT 1 FROM civica_poc.proposal_themes t WHERE t.source=p.source AND t.proposal_id=p.external_id AND t.label ILIKE $N)',`%${query.theme}%`);
  const term=query?.search??query?.q;
  if(term){const n=values.length+1;values.push(searchText(term));where.push(`(p.search_label LIKE '%'||$${n}||'%' OR p.search_summary LIKE '%'||$${n}||'%' OR p.search_type LIKE '%'||$${n}||'%' OR p.search_number LIKE '%'||$${n}||'%' OR EXISTS (SELECT 1 FROM civica_poc.proposal_authors a WHERE a.source=p.source AND a.proposal_id=p.external_id AND a.search_name LIKE '%'||$${n}||'%'))`);}
  return where.join(' AND ');
}
