  const result=await pool.query(`SELECT p.functional_group AS group_key,count(*)::int AS count FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id WHERE ${where} GROUP BY p.functional_group ORDER BY count DESC, group_key`,values);
